import random
from prefect import flow, task, get_run_logger

@task(retries=3, retry_delay_seconds=5)
def fetch_record(record_id: int) -> dict:
    logger = get_run_logger()
    logger.info(f"fetching record {record_id}")
    # Simulate a flaky I/O call that sometimes fails and gets retried
    if random.random() < 0.3:
        raise ConnectionError(f"transient failure for {record_id}")
    return {"id": record_id, "value": record_id * 10}

@task
def transform(record: dict) -> dict:
    record["value"] = record["value"] + 1
    return record

@task
def list_ids() -> list[int]:
    # The set of work is only known at runtime
    return list(range(1, 9))

@flow(name="dynamic-etl")
def dynamic_etl() -> list[dict]:
    logger = get_run_logger()
    ids = list_ids()  # direct call: runs inline, returns a real list

    # Dynamic fan-out: loop over runtime data, submit tasks concurrently
    futures = [fetch_record.submit(i) for i in ids]

    results = []
    for fut in futures:
        record = fut.result()          # resolve the future (or raise)
        if record["value"] % 20 == 0:  # ordinary Python conditional
            record = transform(record) # dependent task waits on this record
        results.append(record)

    logger.info(f"processed {len(results)} records")
    return results

if __name__ == "__main__":
    print(dynamic_etl())
